"use client";

import { ArrowLeftIcon, ExternalLinkIcon, PencilIcon, PlusIcon, SearchIcon } from "lucide-react";
import { useRef } from "react";

import { Link } from "@/components/link";
import {
  buttonClass,
  cardClass,
  iconButtonClass,
  inputClass,
  primaryButtonClass,
} from "@/components/plugins/customers/ui";
import { customerDisplayName } from "@/components/plugins/customers/utils";
import { projectLabels } from "@/components/plugins/projects/labels";
import { ProjectForm } from "@/components/plugins/projects/project-form";
import type {
  ProjectDetailPageProps,
  ProjectNewPageProps,
  ProjectsListProps,
  ProjectsPageProps,
} from "@/components/plugins/projects/types";
import { DeleteProject, ProjectAvatar, ProjectStatusBadge } from "@/components/plugins/projects/ui";
import { safeProjectUrl } from "@/components/plugins/projects/utils";
import { cn } from "@/components/utils/cn";
import {
  tableActionCellClass,
  tableCellClass,
  tableClass,
  tableHeaderClass,
  tablePanelClass,
  tableRowClass,
} from "@/components/utils/table-styles";

export type {
  Project,
  ProjectStatus,
  ProjectSection,
  ProjectFormValues,
  ProjectAssignee,
  ProjectsAppearanceProps,
  ProjectDirectoryProps,
  ProjectsListProps,
  ProjectsPageProps,
  ProjectDetailPageProps,
  ProjectNewPageProps,
} from "@/components/plugins/projects/types";
export type { ProjectsLabels } from "@/components/plugins/projects/labels";

const pageClass = "mx-auto w-full min-w-0 space-y-6 px-4 py-8 text-foreground";

export function ProjectsList({
  projects,
  customers,
  assignees = [],
  customerId,
  search,
  onSearchChange,
  loading,
  error,
  createHref,
  getProjectHref,
  getCustomerHref,
  onDelete,
  labels: overrides,
  linkComponent: ProjectLink = Link,
  className,
}: ProjectsListProps) {
  const labels = { ...projectLabels, ...overrides };
  const root = useRef<HTMLElement>(null);
  const visibleProjects =
    customerId === undefined
      ? projects
      : projects.filter((project) => project.ownerId === customerId);
  const owners = new Map(customers.map((customer) => [customer.id, customer]));
  const assigned = new Map(assignees.map((assignee) => [assignee.id, assignee]));
  return (
    <section
      ref={root}
      tabIndex={-1}
      aria-label={labels.title}
      className={cn(
        tablePanelClass,
        "min-w-0 space-y-5 focus-visible:ring-2 focus-visible:ring-ring",
        className,
      )}
    >
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div className="space-y-1.5">
          <h2 className="font-semibold">{labels.title}</h2>
          <p className="text-sm text-muted-foreground">
            {customerId === undefined ? labels.description : labels.customerDescription}
          </p>
        </div>
        {createHref && (
          <ProjectLink href={createHref} className={primaryButtonClass}>
            <PlusIcon aria-hidden="true" />
            {labels.create}
          </ProjectLink>
        )}
      </header>
      <div className="relative max-w-sm">
        <SearchIcon
          aria-hidden="true"
          className="absolute top-2 left-3 size-4 text-muted-foreground"
        />
        <input
          aria-label={labels.search}
          placeholder={labels.searchPlaceholder}
          value={search}
          onChange={(event) => onSearchChange(event.target.value)}
          className={cn(inputClass, "pl-9")}
        />
      </div>
      {error ? (
        <p role="alert" className="text-sm text-red-600 dark:text-red-400">
          {error}
        </p>
      ) : loading ? (
        <output className="py-10 text-center text-sm text-muted-foreground">
          {labels.loading}
        </output>
      ) : (
        <div className="overflow-x-auto">
          <table className={tableClass}>
            <thead>
              <tr className={tableRowClass}>
                {[
                  labels.name,
                  ...(customerId === undefined ? [labels.owner] : []),
                  labels.assignee,
                  labels.website,
                  labels.status,
                  labels.actions,
                ].map((label, index) => (
                  <th
                    key={index}
                    scope="col"
                    className={
                      index === (customerId === undefined ? 5 : 4)
                        ? tableActionCellClass
                        : tableHeaderClass
                    }
                  >
                    {label}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="[&_tr:last-child]:border-0">
              {visibleProjects.map((project) => {
                const owner = owners.get(project.ownerId);
                const assignee = project.assigneeId ? assigned.get(project.assigneeId) : undefined;
                const website = safeProjectUrl(project.url);
                return (
                  <tr key={project.id} className={tableRowClass}>
                    <td className={tableCellClass}>
                      <ProjectLink
                        href={getProjectHref(project)}
                        className="font-medium hover:underline focus-visible:ring-2 focus-visible:ring-ring"
                      >
                        {project.name}
                      </ProjectLink>
                    </td>
                    {customerId === undefined && (
                      <td className={tableCellClass}>
                        {owner ? (
                          getCustomerHref ? (
                            <ProjectLink
                              href={getCustomerHref(owner)}
                              className="hover:underline focus-visible:ring-2 focus-visible:ring-ring"
                            >
                              {customerDisplayName(owner)}
                            </ProjectLink>
                          ) : (
                            customerDisplayName(owner)
                          )
                        ) : (
                          labels.unavailableOwner
                        )}
                      </td>
                    )}
                    <td className={tableCellClass}>
                      {assignee?.name ??
                        (project.assigneeId ? labels.unavailableAssignee : labels.unassigned)}
                    </td>
                    <td className={tableCellClass}>
                      {website ? (
                        <ProjectLink
                          href={website}
                          target={website.startsWith("/") ? undefined : "_blank"}
                          rel={website.startsWith("/") ? undefined : "noopener noreferrer"}
                          aria-label={labels.visit(project.name)}
                          className={iconButtonClass}
                        >
                          <ExternalLinkIcon aria-hidden="true" />
                        </ProjectLink>
                      ) : (
                        <span className="text-muted-foreground">{labels.noWebsite}</span>
                      )}
                    </td>
                    <td className={tableCellClass}>
                      <ProjectStatusBadge status={project.status} labels={labels} />
                    </td>
                    <td className={tableActionCellClass}>
                      <div className="flex items-start justify-end gap-1">
                        <ProjectLink
                          href={getProjectHref(project)}
                          aria-label={labels.edit(project.name)}
                          className={iconButtonClass}
                        >
                          <PencilIcon aria-hidden="true" />
                        </ProjectLink>
                        {onDelete && (
                          <DeleteProject
                            project={project}
                            onDelete={onDelete}
                            labels={labels}
                            returnFocus={root}
                          />
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {!visibleProjects.length && (
                <tr className={tableRowClass}>
                  <td
                    colSpan={customerId === undefined ? 6 : 5}
                    className={cn(tableCellClass, "py-10 text-center text-muted-foreground")}
                  >
                    {labels.empty}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

export function ProjectsPage({ className, ...props }: ProjectsPageProps) {
  return (
    <div className={cn(pageClass, className)}>
      <h1 className="sr-only">{props.labels?.title ?? projectLabels.title}</h1>
      <ProjectsList {...props} />
    </div>
  );
}

export function ProjectDetailPage({
  project,
  section = "details",
  backHref,
  sectionHrefs,
  onSave,
  onDelete,
  driveContent,
  className,
  labels: overrides,
  linkComponent: ProjectLink = Link,
  ...directory
}: ProjectDetailPageProps) {
  const labels = { ...projectLabels, ...overrides };
  const website = safeProjectUrl(project.url);
  return (
    <div className={cn(pageClass, className)}>
      <ProjectLink href={backHref} className={buttonClass}>
        <ArrowLeftIcon aria-hidden="true" />
        {labels.back}
      </ProjectLink>
      <header className={cn(cardClass, "flex flex-wrap items-center gap-4")}>
        <ProjectAvatar name={project.name} image={project.posterImage} large />
        <div className="min-w-0 flex-1">
          <h1 className="text-xl font-semibold break-words">{project.name}</h1>
          <p className="text-sm break-all text-muted-foreground">
            {website ? (
              <ProjectLink
                href={website}
                className="hover:underline focus-visible:ring-2 focus-visible:ring-ring"
                target={website.startsWith("/") ? undefined : "_blank"}
                rel={website.startsWith("/") ? undefined : "noopener noreferrer"}
              >
                {website}
              </ProjectLink>
            ) : (
              labels.noWebsite
            )}
          </p>
        </div>
        <ProjectStatusBadge status={project.status} labels={labels} />
      </header>
      <nav aria-label={labels.sections} className="flex overflow-x-auto border-b border-border">
        {(["details", "drive"] as const).map((tab) => (
          <ProjectLink
            key={tab}
            href={sectionHrefs[tab]}
            aria-current={section === tab ? "page" : undefined}
            className={cn(
              "shrink-0 border-b-2 border-transparent px-4 py-2 text-sm font-semibold text-muted-foreground hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-inset",
              section === tab && "border-primary text-primary",
            )}
          >
            {labels[tab]}
          </ProjectLink>
        ))}
      </nav>
      {section === "details" ? (
        <ProjectForm
          key={project.id}
          {...directory}
          project={project}
          labels={labels}
          onSubmit={onSave}
          onDelete={onDelete}
          linkComponent={ProjectLink}
        />
      ) : (
        driveContent
      )}
    </div>
  );
}

export function ProjectNewPage({
  backHref,
  onCreate,
  className,
  labels: overrides,
  linkComponent: ProjectLink = Link,
  ...directory
}: ProjectNewPageProps) {
  const labels = { ...projectLabels, ...overrides };
  return (
    <div className={cn(pageClass, className)}>
      <ProjectLink href={backHref} className={buttonClass}>
        <ArrowLeftIcon aria-hidden="true" />
        {labels.back}
      </ProjectLink>
      <header className={cn(cardClass, "space-y-1.5")}>
        <h1 className="font-semibold">{labels.newTitle}</h1>
        <p className="text-sm text-muted-foreground">{labels.newDescription}</p>
      </header>
      <ProjectForm
        key={directory.defaultOwnerId ?? "new"}
        {...directory}
        labels={labels}
        onSubmit={onCreate}
        linkComponent={ProjectLink}
      />
    </div>
  );
}

"use client";

import { useId, useRef, useState, type FormEvent } from "react";

import { Link } from "@/components/link";
import {
  cardClass,
  Feedback,
  inputClass,
  primaryButtonClass,
  useCustomerAction,
} from "@/components/plugins/customers/ui";
import { customerDisplayName } from "@/components/plugins/customers/utils";
import type { ProjectsLabels } from "@/components/plugins/projects/labels";
import type {
  Project,
  ProjectDirectoryProps,
  ProjectFormValues,
  ProjectsAppearanceProps,
} from "@/components/plugins/projects/types";
import { DeleteProject, ProjectPersonPicker } from "@/components/plugins/projects/ui";
import {
  projectFormValues,
  projectStatuses,
  validateProject,
} from "@/components/plugins/projects/utils";
import { cn } from "@/components/utils/cn";

export interface ProjectFormProps
  extends ProjectDirectoryProps, Omit<ProjectsAppearanceProps, "labels"> {
  project?: Project;
  labels: ProjectsLabels;
  onSubmit: (values: ProjectFormValues) => Promise<void>;
  onDelete?: (id: string) => Promise<void>;
}

export function ProjectForm({
  project,
  labels,
  onSubmit,
  onDelete,
  customers,
  customersLoading,
  customersError,
  createCustomerHref,
  assignees = [],
  assigneesLoading,
  assigneesError,
  defaultOwnerId,
  lockOwner,
  linkComponent: ProjectLink = Link,
  className,
}: ProjectFormProps) {
  const id = useId();
  const formRef = useRef<HTMLFormElement>(null);
  const [values, setValues] = useState(() => projectFormValues(project, defaultOwnerId));
  const [errors, setErrors] = useState<Partial<Record<keyof ProjectFormValues, string>>>({});
  const [deleting, setDeleting] = useState(false);
  const action = useCustomerAction(labels.actionError);
  const pending = action.pending || deleting;
  const ownerId = lockOwner ? (project?.ownerId ?? defaultOwnerId ?? "") : values.ownerId;
  const directoriesUnavailable = Boolean(
    customersLoading || customersError || assigneesLoading || assigneesError,
  );
  const noCustomers = !customersLoading && !customersError && !customers.length;

  function change<K extends keyof ProjectFormValues>(name: K, value: ProjectFormValues[K]) {
    setValues((current) => ({ ...current, [name]: value }));
    setErrors((current) => ({ ...current, [name]: undefined }));
  }
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (pending || directoriesUnavailable) return;
    const normalized = {
      ...values,
      name: values.name.trim(),
      description: values.description.trim(),
      url: values.url.trim(),
      ownerId,
    };
    const nextErrors = validateProject(normalized, customers, assignees, labels);
    setErrors(nextErrors);
    const firstInvalid = Object.keys(nextErrors)[0];
    if (firstInvalid) {
      (event.currentTarget.elements.namedItem(firstInvalid) as HTMLElement | null)?.focus();
      return;
    }
    if (await action.run(() => onSubmit(normalized), project ? labels.saved : labels.created))
      setValues(normalized);
  }
  function error(name: keyof ProjectFormValues) {
    return errors[name] ? (
      <p id={`${id}-${name}-error`} role="alert" className="text-sm text-red-600 dark:text-red-400">
        {errors[name]}
      </p>
    ) : null;
  }
  function fieldProps(name: keyof ProjectFormValues) {
    return {
      id: `${id}-${name}`,
      name,
      "aria-invalid": Boolean(errors[name]),
      "aria-describedby": errors[name] ? `${id}-${name}-error` : undefined,
      className: inputClass,
    };
  }
  return (
    <div className={className}>
      <form
        ref={formRef}
        tabIndex={-1}
        noValidate
        onSubmit={submit}
        aria-busy={pending}
        className={cn(cardClass, "space-y-5")}
      >
        {project && (
          <div className="space-y-1.5">
            <h2 className="font-semibold">{labels.detailsTitle}</h2>
            <p className="text-sm text-muted-foreground">{labels.detailsDescription}</p>
          </div>
        )}
        <fieldset disabled={pending} className="grid min-w-0 grid-cols-1 gap-5 md:grid-cols-2">
          <div className="space-y-2">
            <label htmlFor={`${id}-name`} className="block text-sm font-semibold">
              {labels.name} *
            </label>
            <input
              {...fieldProps("name")}
              required
              value={values.name}
              onChange={(event) => change("name", event.target.value)}
            />
            {error("name")}
          </div>
          <div className="space-y-2">
            <label htmlFor={`${id}-status`} className="block text-sm font-semibold">
              {labels.status}
            </label>
            <select
              {...fieldProps("status")}
              value={values.status}
              onChange={(event) => {
                const status = projectStatuses.find((entry) => entry === event.target.value);
                if (status) change("status", status);
              }}
            >
              {projectStatuses.map((status) => (
                <option key={status} value={status}>
                  {labels[status]}
                </option>
              ))}
            </select>
            {error("status")}
          </div>
          <div className="space-y-2 md:col-span-2">
            <label htmlFor={`${id}-description`} className="block text-sm font-semibold">
              {labels.projectDescription}
            </label>
            <textarea
              {...fieldProps("description")}
              className={cn(inputClass, "h-auto py-2")}
              rows={3}
              value={values.description}
              onChange={(event) => change("description", event.target.value)}
            />
            {error("description")}
          </div>
          <div className="space-y-2 md:col-span-2">
            <label htmlFor={`${id}-url`} className="block text-sm font-semibold">
              {labels.url}
            </label>
            <input
              {...fieldProps("url")}
              placeholder={labels.urlPlaceholder}
              value={values.url}
              onChange={(event) => change("url", event.target.value)}
            />
            {error("url")}
          </div>
          <div className="min-w-0 space-y-2">
            <label htmlFor={`${id}-ownerId`} className="block text-sm font-semibold">
              {labels.owner} *
            </label>
            <ProjectPersonPicker
              id={`${id}-ownerId`}
              name="ownerId"
              candidates={customers.map((customer) => ({
                ...customer,
                name: customerDisplayName(customer),
              }))}
              value={ownerId}
              onChange={(value) => change("ownerId", value)}
              title={labels.selectOwner}
              searchLabel={labels.searchOwners}
              unavailableLabel={labels.unavailableOwner}
              labels={labels}
              disabled={
                pending || lockOwner || customersLoading || Boolean(customersError) || noCustomers
              }
              required
              error={errors.ownerId}
            />
            {customersError ? (
              <p role="alert" className="text-sm text-red-600 dark:text-red-400">
                {customersError}
              </p>
            ) : customersLoading ? (
              <output className="text-sm text-muted-foreground">{labels.customersLoading}</output>
            ) : noCustomers ? (
              <div className="space-y-2 text-sm">
                <output>{labels.noCustomers}</output>
                {createCustomerHref && (
                  <ProjectLink
                    href={createCustomerHref}
                    className="underline focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    {labels.createCustomer}
                  </ProjectLink>
                )}
              </div>
            ) : null}
            {error("ownerId")}
          </div>
          <div className="min-w-0 space-y-2">
            <label htmlFor={`${id}-assigneeId`} className="block text-sm font-semibold">
              {labels.assignee}
            </label>
            <ProjectPersonPicker
              id={`${id}-assigneeId`}
              name="assigneeId"
              candidates={assignees}
              value={values.assigneeId}
              onChange={(value) => change("assigneeId", value)}
              title={labels.selectAssignee}
              searchLabel={labels.searchAssignees}
              unavailableLabel={labels.unavailableAssignee}
              labels={labels}
              disabled={pending || assigneesLoading || Boolean(assigneesError)}
              clearable
              error={errors.assigneeId}
            />
            {assigneesError ? (
              <p role="alert" className="text-sm text-red-600 dark:text-red-400">
                {assigneesError}
              </p>
            ) : assigneesLoading ? (
              <output className="text-sm text-muted-foreground">{labels.assigneesLoading}</output>
            ) : null}
            {error("assigneeId")}
          </div>
          <div className="flex justify-end md:col-span-2">
            <button
              type="submit"
              disabled={directoriesUnavailable || noCustomers}
              className={primaryButtonClass}
            >
              {pending ? labels.pending : project ? labels.save : labels.create}
            </button>
          </div>
        </fieldset>
        <Feedback feedback={action.feedback} />
      </form>
      {project && onDelete && (
        <div className="mt-6">
          <DeleteProject
            project={project}
            onDelete={onDelete}
            labels={labels}
            disabled={pending}
            onPendingChange={setDeleting}
            returnFocus={formRef}
          />
        </div>
      )}
    </div>
  );
}

"use client";

import { Avatar } from "@base-ui/react/avatar";
import { Dialog } from "@base-ui/react/dialog";
import { CheckIcon, ChevronDownIcon, SearchIcon, Trash2Icon } from "lucide-react";
import { useRef, useState, type RefObject } from "react";

import {
  buttonClass,
  iconButtonClass,
  cardClass,
  Feedback,
  inputClass,
  outlineButtonClass,
  useCustomerAction,
} from "@/components/plugins/customers/ui";
import { customerInitials } from "@/components/plugins/customers/utils";
import type { ProjectsLabels } from "@/components/plugins/projects/labels";
import type { Project, ProjectAssignee, ProjectStatus } from "@/components/plugins/projects/types";
import { cn } from "@/components/utils/cn";

const popupClass = cn(
  cardClass,
  "fixed top-1/2 left-1/2 z-50 max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 space-y-5 overflow-y-auto shadow-xl",
);

export function ProjectAvatar({
  name,
  image,
  large = false,
}: {
  name: string;
  image?: string | null;
  large?: boolean;
}) {
  return (
    <Avatar.Root
      className={cn(
        "flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-full border border-border text-sm",
        large && "size-16 text-xl",
      )}
    >
      <Avatar.Image src={image ?? undefined} alt={name} className="size-full object-contain" />
      <Avatar.Fallback>{customerInitials(name, "")}</Avatar.Fallback>
    </Avatar.Root>
  );
}

export function ProjectStatusBadge({
  status,
  labels,
}: {
  status: ProjectStatus;
  labels: ProjectsLabels;
}) {
  return (
    <span
      className={cn(
        "inline-flex shrink-0 rounded-full border border-border px-2 py-0.5 text-xs font-semibold",
        status === "production"
          ? "bg-primary text-primary-foreground"
          : status === "under-construction"
            ? "bg-accent text-accent-foreground"
            : status === "prospect"
              ? "bg-secondary text-secondary-foreground"
              : "bg-muted text-muted-foreground",
      )}
    >
      {labels[status]}
    </span>
  );
}

export interface ProjectPersonPickerProps {
  id: string;
  name: string;
  candidates: readonly ProjectAssignee[];
  value: string;
  onChange: (id: string) => void;
  title: string;
  searchLabel: string;
  unavailableLabel: string;
  labels: ProjectsLabels;
  disabled?: boolean;
  required?: boolean;
  error?: string;
  clearable?: boolean;
}

export function ProjectPersonPicker({
  id,
  name,
  candidates,
  value,
  onChange,
  title,
  searchLabel,
  unavailableLabel,
  labels,
  disabled,
  required,
  error,
  clearable,
}: ProjectPersonPickerProps) {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");
  const selected = candidates.find((candidate) => candidate.id === value);
  const query = search.trim().toLowerCase();
  const filtered = candidates.filter((candidate) =>
    [candidate.name, candidate.email].some((text) => text?.toLowerCase().includes(query)),
  );
  function select(id: string) {
    onChange(id);
    setOpen(false);
    setSearch("");
  }
  return (
    <Dialog.Root
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        if (!next) setSearch("");
      }}
    >
      <Dialog.Trigger
        id={id}
        name={name}
        disabled={disabled}
        aria-invalid={Boolean(error)}
        aria-describedby={error ? `${id}-error` : undefined}
        aria-label={`${title}${required ? " *" : ""}`}
        className={cn(
          buttonClass,
          "min-h-14 w-full min-w-0 justify-start border border-border px-3 text-left aria-invalid:ring-2 aria-invalid:ring-red-600",
        )}
      >
        <ProjectAvatar name={selected?.name ?? ""} image={selected?.image} />
        <span className="min-w-0 flex-1">
          <span className="block truncate font-semibold">
            {selected?.name ?? (value ? unavailableLabel : title)}
          </span>
          {selected?.email && (
            <span className="block truncate text-xs font-normal text-muted-foreground">
              {selected.email}
            </span>
          )}
        </span>
        <ChevronDownIcon aria-hidden="true" />
      </Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup className={popupClass}>
          <Dialog.Title className="text-lg font-semibold">{title}</Dialog.Title>
          <Dialog.Description className="text-sm text-muted-foreground">
            {labels.pickerDescription}
          </Dialog.Description>
          <div className="relative">
            <SearchIcon
              aria-hidden="true"
              className="absolute top-2 left-3 size-4 text-muted-foreground"
            />
            <input
              aria-label={searchLabel}
              placeholder={searchLabel}
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              className={cn(inputClass, "pl-9")}
            />
          </div>
          <div className="max-h-[min(24rem,45dvh)] space-y-2 overflow-y-auto p-1">
            {clearable && (
              <button
                type="button"
                className={cn(buttonClass, "w-full justify-start border border-border")}
                aria-pressed={!value}
                onClick={() => select("")}
              >
                {labels.clearAssignee}
              </button>
            )}
            {filtered.map((candidate) => (
              <button
                key={candidate.id}
                type="button"
                className={cn(
                  buttonClass,
                  "w-full min-w-0 justify-start rounded-xl border border-border py-2 text-left",
                  candidate.id === value && "bg-accent text-accent-foreground",
                )}
                aria-pressed={candidate.id === value}
                onClick={() => select(candidate.id)}
              >
                <ProjectAvatar name={candidate.name} image={candidate.image} />
                <span className="min-w-0 flex-1">
                  <span className="block truncate font-semibold">{candidate.name}</span>
                  <span className="block truncate text-xs text-muted-foreground">
                    {candidate.email}
                  </span>
                </span>
                {candidate.id === value && <CheckIcon aria-hidden="true" />}
              </button>
            ))}
            {!filtered.length && (
              <output className="py-4 text-center text-sm text-muted-foreground">
                {labels.noMatches}
              </output>
            )}
          </div>
          <div className="flex justify-end">
            <Dialog.Close className={outlineButtonClass}>{labels.close}</Dialog.Close>
          </div>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

export function DeleteProject({
  project,
  onDelete,
  labels,
  disabled,
  onPendingChange,
  returnFocus,
}: {
  project: Project;
  onDelete: (id: string) => Promise<void>;
  labels: ProjectsLabels;
  disabled?: boolean;
  onPendingChange?: (pending: boolean) => void;
  returnFocus?: RefObject<HTMLElement | null>;
}) {
  const [open, setOpen] = useState(false);
  const action = useCustomerAction(labels.actionError);
  const trigger = useRef<HTMLButtonElement>(null);
  return (
    <div>
      <Dialog.Root
        open={open}
        onOpenChange={(next) => {
          if (!action.pending) setOpen(next);
        }}
      >
        <Dialog.Trigger
          ref={trigger}
          disabled={disabled || action.pending}
          className={cn(iconButtonClass, "text-destructive hover:text-destructive")}
          aria-label={labels.deleteProject}
        >
          <Trash2Icon aria-hidden="true" />
        </Dialog.Trigger>
        <Dialog.Portal>
          <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
          <Dialog.Popup
            className={popupClass}
            finalFocus={() =>
              trigger.current?.isConnected ? trigger.current : (returnFocus?.current ?? true)
            }
          >
            <Dialog.Title className="text-lg font-semibold">{labels.deleteProject}</Dialog.Title>
            <Dialog.Description className="text-sm text-muted-foreground">
              {labels.deleteDescription(project.name)}
            </Dialog.Description>
            <Feedback feedback={action.feedback} />
            <div className="flex justify-end gap-2">
              <Dialog.Close disabled={action.pending} className={outlineButtonClass}>
                {labels.cancel}
              </Dialog.Close>
              <button
                type="button"
                disabled={action.pending}
                aria-busy={action.pending}
                className={cn(
                  buttonClass,
                  "bg-destructive text-destructive-foreground hover:bg-destructive/90 hover:text-destructive-foreground",
                )}
                onClick={async () => {
                  const success = await action.run(async () => {
                    onPendingChange?.(true);
                    try {
                      await onDelete(project.id);
                    } finally {
                      onPendingChange?.(false);
                    }
                  }, labels.deleted);
                  if (success) {
                    setOpen(false);
                    if (!trigger.current?.isConnected) returnFocus?.current?.focus();
                  }
                }}
              >
                {action.pending ? labels.pending : labels.confirmDelete}
              </button>
            </div>
          </Dialog.Popup>
        </Dialog.Portal>
      </Dialog.Root>
      {!open && <Feedback feedback={action.feedback} />}
    </div>
  );
}

